<style>.dr-thumb{display:block;width:112px;height:84px;object-fit:contain;background:#f1f5f9;border:1px solid #dbe5ef;border-radius:9px;flex-shrink:0}.dr-flex{display:flex;align-items:center;gap:14px;min-width:0}.dr-flex>div{min-width:0;overflow-wrap:anywhere}.dr-pill{display:inline-block;border-radius:20px;padding:5px 10px;background:#edf2f7;color:#38536b;font-size:12px;font-weight:700}.dr-pill.Published,.dr-pill.Approved{background:#e0f3e9;color:#087451}.dr-pill.Submitted{background:#fff1d4;color:#855500}.dr-pill.Withdrawn{background:#fce8e8;color:#a32e2e}.dr-metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:12px;margin:16px 0}.dr-metric{background:white;border:1px solid #dbe5ef;border-radius:12px;padding:16px}.dr-metric strong{display:block;font-size:26px;color:#087f8c}.dr-actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.dr .danger{background:#a32e2e}.dr .secondary{background:#e8eff5;color:#173c67}.dr table td{overflow-wrap:anywhere}.dr h2{font-size:18px;font-weight:700;margin-bottom:12px}.dr summary{cursor:pointer}.dr-client .dr-thumb{width:180px;height:135px}.dr-client .dr-flex{align-items:flex-start}.dr-client .dr-primary{display:inline-block;background:#174b77;color:white;padding:10px 16px;border-radius:8px;font-weight:700}.dr-client button{cursor:pointer}.dr-client .approve{background:#087451;color:white;border:0;padding:11px 16px;border-radius:8px;font-weight:700}.dr-client .changes{background:white;color:#934b18;border:1px solid #c89a73;padding:10px 16px;border-radius:8px;font-weight:700}@media(max-width:600px){.dr-client .dr-flex{flex-direction:column}.dr-client .dr-thumb{width:100%;height:180px}.dr-flex{gap:8px}.dr-thumb{width:80px;height:60px}}</style>